import math
h = 6.62607015e-34
hbar = h / (2 * math.pi)
me = 9.1093837139e-31
q = 1.602176634e-19

def T(U_eV, d_nm):
    kappa = math.sqrt(2 * me * U_eV * q) / hbar
    return math.exp(-2 * kappa * d_nm * 1e-9)

onceki = None
for d in [1.0, 1.5, 2.0, 2.5]:
    t = T(3.0, d)
    if onceki is None:
        print(d, '%.2e' % t)
    else:
        print(d, '%.2e' % t, round(math.log10(onceki / t), 2))
    onceki = t

import math
a = 0.246

def tup(n, m):
    L = a * math.sqrt(n*n + n*m + m*m)
    d = L / math.pi
    tur = 'metalik' if (n - m) % 3 == 0 else 'yariiletken'
    if n == m:
        bicim = 'koltuk'
    elif m == 0:
        bicim = 'zikzak'
    else:
        bicim = 'kiral'
    return round(d, 3), bicim, tur

for n, m in [(5, 5), (9, 0), (10, 0), (6, 4), (7, 1)]:
    print(n, m, *tup(n, m))

